import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0 # Should not happen for B_k in this context
    return reduce(gcd, numbers)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1 # LCM of an empty set is conventionally 1 or 0, but here A_k is never empty
    return reduce(lcm, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    if n < 2:
        return 0

    good_partitions = 0

    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        L = list_lcm(A_k)
        G = list_gcd(B_k)

        if L == G:
            good_partitions += 1

    return good_partitions

# --- Search Strategy ---
# Since the sequence elements can be arbitrarily large, we must constrain the search.
# We will search sequences where a_n <= M for a small M, and increase M if needed.

def systematic_search(n, max_a):
    """Searches for sequences of length n up to max element max_a."""
    print(f"--- Searching for n={n}, max_a={max_a} ---")

    found_results = {} # {N_good: minimum_sequence}

    # Use itertools.product, but adapted for strictly increasing sequences

    from itertools import combinations

    # Generate all strictly increasing sequences of length n from {1, 2, ..., max_a}
    potential_sequences = list(combinations(range(1, max_a + 1), n))

    for seq_tuple in potential_sequences:
        sequence = list(seq_tuple)
        N_good = count_good_partitions(sequence)

        if N_good not in found_results:
            found_results[N_good] = sequence
        # Since we generate sequences in lexicographical order, the first one found is the 'smallest'
        # in terms of element values, which is sufficient for this task.

    return found_results

# --- Execution for n=3, 4, 5, 6 ---

# N=3 (Max N_good = 2)
results_n3 = systematic_search(3, 10)
print(f"\nResults for N=3 (up to 10): {results_n3}")

# N=4 (Max N_good = 3)
results_n4 = systematic_search(4, 10)
print(f"\nResults for N=4 (up to 10): {results_n4}")

# N=5 (Max N_good = 4)
# This is likely too large to complete quickly with max_a=10. We will use a smaller bound first.
results_n5_small = systematic_search(5, 8)
print(f"\nResults for N=5 (up to 8): {results_n5_small}")


